import { useRouter } from 'next/router';
import { useEffect, useState } from 'react';
import '../Forum.css'
import { listAll, getById } from '@/services/ForumService';
import Comments from '@/components/Comments/Comments';

export default function Forum() {
  const router = useRouter();
  const { forumId } = router.query;
  const [forumData, setForumData] = useState<any>([]);
  const [newCommentInput, setNewCommentInput] = useState<any>([]);
  const [replyToCommentId, setReplyToCommentId] = useState<any>([]);

  useEffect(() => {
    if (forumId) {
      fetchForum();
    }
  }, [forumId]);

  const fetchForum = async () => {
    const forum = await getById(parseInt(forumId as string));
    setForumData(forum);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    let comment = {
      'forumId': forumData.id,
      'usernameAuthor': 'var3',
      'replyToCommentId': replyToCommentId || null,
      'content': newCommentInput,
    }
    console.log(comment);
  };

  return (
    <div className='forum-page-container'>
      <h1>{forumData.title}</h1>
      <h4>Descrição: {forumData.description}</h4>
      <p>Autor: {forumData.username}</p>
      <pre>{JSON.stringify(forumData.related_movie)}</pre>

      <div className="comments-container">
        <h2 className="comments-title">Comentários</h2>
        <div className="comment-form">
          <input 
            type="text" 
            placeholder="Digite seu comentário..." 
            className="comment-input"
            value={newCommentInput}
            onChange={(e) => setNewCommentInput(e.target.value)}
          />
          <button className="submit-button" onClick={handleSubmit}>Enviar</button>
        </div>
        
        {/* Usando o componente Comments com forumId */}
        <Comments forumId={parseInt(forumId as string)} />
      </div>
    </div>
  );
}